import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

// 1 行目の N は使わない
const [, second] = input;
const a = second.split(" ").map(Number);

// 隣り合う差の絶対値を配列にする
const diffs = a.slice(1).map((v, i) => Math.abs(v - a[i]));

// 最大値を 1 回の走査で求める
const answer = diffs.reduce((max, d) => Math.max(max, d), 0);
console.log(answer);
